        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        int[] lines = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            lines[i] = (int) in.nval;
